   codeJava:`public class Solution { public int majorityElement(int[] nums) { int c=0, cand=0; for(int x:nums){ if(c==0) cand=x; c+=(x==cand)?1:-1; } return cand; } }`,
   codePython:`def majorityElement(nums):\n    cand, count = 0, 0\n    for x in nums:\n        if count == 0: cand = x\n        count += 1 if x == cand else -1\n    return cand`
