   codeCpp:`#include <string>\nusing namespace std;\nbool isSubsequence(string s, string t) {\n    int i = 0, j = 0;\n    while (i < s.length() && j < t.length()) {\n        if (s[i] == t[j]) i++; j++;\n    }\n    return i == s.length();\n}`,
   codeJava:`public class Solution { public boolean isSubsequence(String s, String t) { int i=0, j=0; while(i<s.length()&&j<t.length()){ if(s.charAt(i)==t.charAt(j)) i++; j++; } return i==s.length(); } }`,
   codePython:`def isSubsequence(s: str, t: str) -> bool:\n    i = j = 0\n    while i < len(s) and j < len(t):\n        if s[i] == t[j]: i += 1\n        j += 1\n    return i == len(s)`
