   statement:"Given a 3-digit number N, find whether it is an Armstrong number or not. An Armstrong number of three digits is an integer such that sum of cubes of its digits is equal to number itself.",
   exampleInput:"N = 153", exampleOutput:"true",
   codeCpp:`bool armstrongNumber(int n) {\n    int sum = 0, temp = n;\n    while (temp > 0) { int d = temp % 10; sum += d * d * d; temp /= 10; }\n    return sum == n;\n}`,
   codeJava:`public class Solution { static boolean armstrongNumber(int n){ int sum=0, temp=n; while(temp>0){ int d=temp%10; sum+=d*d*d; temp/=10; } return sum==n; } }`,
   codePython:`def armstrongNumber(n):\n    return sum(int(d)**3 for d in str(n)) == n`
